-- V31 — E-way bill use case works from the UI (the last M10 sub-flow).
-- The e-way flow had no projection (workflow instance + m10_eway_bill row were
-- never linked) and its pages were status-flip lists. Fixed:
--   1. Projection M10.EwayBill -> m10_eway_bill (tenant 1, matching the other
--      M10 projections): maps the GST fields, stamps EWB-{tenant}-{instance} as
--      the number on submit, freezes generated_at on GENERATED.
--   2. EwayBill registered with value/display=ewb_number so it's pickable.
--   3. eway-create rebuilt as a real GST create-form (doc type/no/date/value,
--      supply + sub-supply type, GSTINs, transport, distance) whose Submit
--      button is a create-flow DRAFT->SUBMITTED.
--   4. eway-cancel repurposed as "Manage E-way": pick a submitted bill by EWB
--      number, then Generate IRN / Conditional Approval / Cancel.
-- Verified: create+submit writes the bill with an EWB number + GST data;
-- Generate IRN moves it to GENERATED with a timestamp. All 11 M10 workflows
-- still walk end-to-end. Idempotent.

INSERT INTO m0_workflow_projection
  (tenant_id, workflow_code, target_table, key_column, state_columns, number_column, number_pattern, terminal_states, terminal_ts_column, field_map_json)
SELECT 1,'M10.EwayBill','m10_eway_bill','workflow_instance_id','ewb_status,current_step','ewb_number','EWB-{tenant}-{instance}','GENERATED,CANCELLED,EXPIRED','generated_at',
  JSON_OBJECT('source_doc_type',JSON_ARRAY('source_doc_type'),'source_doc_no',JSON_ARRAY('source_doc_no'),
    'source_doc_date',JSON_ARRAY('source_doc_date'),'supply_type',JSON_ARRAY('supply_type'),
    'sub_supply_type',JSON_ARRAY('sub_supply_type'),'doc_value',JSON_ARRAY('doc_value'),
    'from_gstin',JSON_ARRAY('from_gstin'),'to_gstin',JSON_ARRAY('to_gstin'),
    'transport_mode',JSON_ARRAY('transport_mode'),'vehicle_no',JSON_ARRAY('vehicle_no'),
    'transporter_name',JSON_ARRAY('transporter_name'),'distance_km',JSON_ARRAY('distance_km'),
    'notes',JSON_ARRAY('notes'),'cancel_reason',JSON_ARRAY('cancel_reason'))
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM m0_workflow_projection WHERE workflow_code='M10.EwayBill' AND target_table='m10_eway_bill');
UPDATE entity_registry SET value_column='ewb_number', display_column='ewb_number' WHERE code='EwayBill' AND (value_column IS NULL OR value_column='');
UPDATE page_definition SET title='Manage E-way Bill' WHERE code='aria:eway-cancel';
UPDATE page_version pv JOIN page_definition pd ON pd.current_version_id=pv.id
SET pv.body_json='{"kind": "layout", "schemaVersion": 2, "entity": "EwayBill", "layout": [{"kind": "Grid", "columns": 12, "gap": 16, "children": [{"kind": "Section", "title": "New E-way Bill", "span": 12, "subtitle": "Fill the source document + transport details and submit. An EWB number is assigned on submit; generate the IRN from Manage E-way.", "children": [{"kind": "Form", "bindings": {"fields": [{"name": "source_doc_type", "label": "Document Type", "type": "select", "required": true, "options": [{"value": "INVOICE", "label": "Tax Invoice"}, {"value": "BILL", "label": "Bill of Supply"}, {"value": "CHALLAN", "label": "Delivery Challan"}, {"value": "CREDIT_NOTE", "label": "Credit Note"}]}, {"name": "source_doc_no", "label": "Document No", "type": "text", "required": true}, {"name": "source_doc_date", "label": "Document Date", "type": "date"}, {"name": "doc_value", "label": "Document Value (₹)", "type": "number", "required": true}, {"name": "supply_type", "label": "Supply Type", "type": "select", "required": true, "options": [{"value": "OUTWARD", "label": "Outward"}, {"value": "INWARD", "label": "Inward"}]}, {"name": "sub_supply_type", "label": "Sub-supply Type", "type": "select", "required": true, "options": [{"value": "SUPPLY", "label": "Supply"}, {"value": "EXPORT", "label": "Export"}, {"value": "JOB_WORK", "label": "Job Work"}, {"value": "SKD_CKD", "label": "SKD/CKD"}, {"value": "RECIPIENT_NOT_KNOWN", "label": "Recipient not known"}, {"value": "LINE_SALES", "label": "Line Sales"}, {"value": "SALES_RETURN", "label": "Sales Return"}, {"value": "OTHERS", "label": "Others"}]}, {"name": "from_gstin", "label": "From GSTIN", "type": "text", "required": false}, {"name": "to_gstin", "label": "To GSTIN", "type": "text", "required": false}, {"name": "transport_mode", "label": "Transport Mode", "type": "select", "required": false, "options": [{"value": "ROAD", "label": "Road"}, {"value": "RAIL", "label": "Rail"}, {"value": "AIR", "label": "Air"}, {"value": "SHIP", "label": "Ship"}]}, {"name": "vehicle_no", "label": "Vehicle No", "type": "text", "required": false}, {"name": "transporter_name", "label": "Transporter", "type": "text", "required": false}, {"name": "distance_km", "label": "Distance (km)", "type": "number", "required": false}, {"name": "notes", "label": "Notes", "type": "textarea"}]}}, {"kind": "Stack", "direction": "row", "gap": 12, "children": [{"kind": "WorkflowActionButton", "label": "Submit E-way Bill", "action": "workflow.transition", "workflowCode": "M10.EwayBill", "targetState": "SUBMITTED", "color": "primary", "onSuccessOpen": {"page": "aria:eway-cancel", "lookupEntity": "EwayBill", "lookupField": "workflow_instance_id", "param": "id"}}]}]}]}]}'
WHERE pd.code='aria:eway-create' AND pv.body_json NOT LIKE '%New E-way Bill%';
UPDATE page_version pv JOIN page_definition pd ON pd.current_version_id=pv.id
SET pv.body_json='{"kind": "layout", "schemaVersion": 2, "entity": "EwayBill", "layout": [{"kind": "Grid", "columns": 12, "gap": 16, "children": [{"kind": "Section", "title": "Manage E-way Bill", "span": 12, "subtitle": "Pick a submitted E-way bill by its EWB number, then Generate the IRN, put it on Conditional approval, or Cancel it with a reason.", "children": [{"kind": "Form", "bindings": {"fields": [{"name": "ewbNumber", "label": "EWB Number (pick / type)", "type": "select", "required": true, "freeSolo": true, "scannable": true, "optionsSource": {"type": "entity", "entity": "EwayBill", "valueField": "ewb_number", "labelField": "ewb_number"}, "onChangeFill": {"instanceId": "workflow_instance_id", "source_doc_no": "source_doc_no", "doc_value": "doc_value", "ewb_status": "ewb_status", "vehicle_no": "vehicle_no"}}, {"name": "source_doc_no", "label": "Document No", "type": "text", "readOnly": true}, {"name": "doc_value", "label": "Document Value (₹)", "type": "text", "readOnly": true}, {"name": "vehicle_no", "label": "Vehicle", "type": "text", "readOnly": true}, {"name": "ewb_status", "label": "Status", "type": "text", "readOnly": true}, {"name": "cancel_reason", "label": "Cancel reason (required to cancel)", "type": "textarea"}]}}, {"kind": "Stack", "direction": "row", "gap": 12, "children": [{"kind": "WorkflowActionButton", "label": "✓ Generate IRN", "action": "workflow.transition", "pageCode": "aria:eway-create", "instanceId": "{{form.instanceId}}", "targetState": "GENERATED", "color": "primary"}, {"kind": "WorkflowActionButton", "label": "◐ Conditional Approval", "action": "workflow.transition", "pageCode": "aria:eway-conditional", "instanceId": "{{form.instanceId}}", "targetState": "CONDITIONAL_APPROVAL", "color": "secondary"}, {"kind": "WorkflowActionButton", "label": "✗ Cancel E-way", "action": "workflow.transition", "pageCode": "aria:eway-cancel", "instanceId": "{{form.instanceId}}", "targetState": "CANCELLED", "color": "error"}]}]}]}]}'
WHERE pd.code='aria:eway-cancel' AND pv.body_json NOT LIKE '%Manage E-way Bill%';
